package cli

import (
	"fmt"
	"io"
	"strings"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/search"
	"github.com/entireio/cli/cmd/entire/cli/stringutil"
)

// columnLayout holds computed column widths for the search results table.
type columnLayout struct {
	id     int
	branch int
	prompt int
	author int
	age    int
}

// searchModel is the bubbletea model for interactive search results.
type searchModel struct {
	results []search.Result
	cursor  int
	query   string
	total   int
	width   int
	styles  statusStyles
}

func newSearchModel(results []search.Result, query string, total int, styles statusStyles) searchModel {
	return searchModel{
		results: results,
		cursor:  0,
		query:   query,
		total:   total,
		width:   styles.width,
		styles:  styles,
	}
}

func (m searchModel) Init() tea.Cmd {
	return nil
}

func (m searchModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		switch msg.String() {
		case "q", "ctrl+c", "esc":
			return m, tea.Quit
		case "up", "k":
			if m.cursor > 0 {
				m.cursor--
			}
		case "down", "j":
			if m.cursor < len(m.results)-1 {
				m.cursor++
			}
		}
	case tea.WindowSizeMsg:
		m.width = msg.Width
	}
	return m, nil
}

func (m searchModel) View() string {
	if m.width == 0 {
		return ""
	}

	var b strings.Builder

	// Header
	header := fmt.Sprintf("Found %d checkpoints matching %q", m.total, m.query)
	b.WriteString(m.styles.render(m.styles.gray, header))
	b.WriteString("\n\n")

	cols := computeColumns(m.width)

	// Table header
	headerRow := fmt.Sprintf("%-*s  %-*s  %-*s  %-*s  %s",
		cols.id, "ID",
		cols.branch, "BRANCH",
		cols.prompt, "PROMPT",
		cols.author, "AUTHOR",
		"AGE",
	)
	b.WriteString(m.styles.render(m.styles.gray, headerRow))
	b.WriteString("\n")

	// Table rows
	for i, r := range m.results {
		row := m.renderRow(i, r, cols)
		if i == m.cursor {
			if m.styles.colorEnabled {
				highlight := lipgloss.NewStyle().Reverse(true)
				row = highlight.Render(row)
			} else {
				row = "> " + row
			}
		} else if !m.styles.colorEnabled {
			row = "  " + row
		}
		b.WriteString(row)
		b.WriteString("\n")
	}

	// Separator
	b.WriteString("\n")
	b.WriteString(m.styles.horizontalRule(m.width))
	b.WriteString("\n\n")

	// Detail panel
	if m.cursor >= 0 && m.cursor < len(m.results) {
		b.WriteString(m.renderDetail(m.results[m.cursor]))
	}

	// Footer
	b.WriteString("\n")
	footer := m.styles.render(m.styles.gray, "↑/↓") + " navigate  " +
		m.styles.render(m.styles.gray, "q") + " quit"
	b.WriteString(footer)
	b.WriteString("\n")

	return b.String()
}

func (m searchModel) renderRow(idx int, r search.Result, cols columnLayout) string {
	_ = idx
	id := stringutil.TruncateRunes(r.Data.ID, cols.id, "")
	branch := stringutil.TruncateRunes(r.Data.Branch, cols.branch, "...")
	prompt := stringutil.TruncateRunes(
		stringutil.CollapseWhitespace(r.Data.Prompt), cols.prompt, "...",
	)
	author := stringutil.TruncateRunes(r.Data.Author, cols.author, "...")
	age := formatSearchAge(r.Data.CreatedAt)

	return fmt.Sprintf("%-*s  %-*s  %-*s  %-*s  %s",
		cols.id, m.styles.render(m.styles.agent, id),
		cols.branch, m.styles.render(m.styles.cyan, branch),
		cols.prompt, prompt,
		cols.author, m.styles.render(m.styles.gray, author),
		m.styles.render(m.styles.gray, age),
	)
}

func (m searchModel) renderDetail(r search.Result) string {
	const labelWidth = 14
	var b strings.Builder

	lines := []struct {
		label string
		value string
	}{
		{"ID", r.Data.ID},
		{"Type", r.Type},
		{"Prompt", r.Data.Prompt},
		{"Commit", formatCommit(r.Data.CommitSHA, r.Data.CommitMessage)},
		{"Branch", r.Data.Branch},
		{"Repo", r.Data.Org + "/" + r.Data.Repo},
		{"Author", formatAuthor(r.Data.Author, r.Data.AuthorUsername)},
		{"Created", formatCreatedAt(r.Data.CreatedAt)},
		{"Match", formatMatch(r.Meta)},
		{"Snippet", derefStr(ptrFromStr(r.Meta.Snippet), "—")},
	}

	for _, l := range lines {
		label := fmt.Sprintf("%-*s", labelWidth, l.label)
		b.WriteString(m.styles.render(m.styles.gray, label))
		b.WriteString(l.value)
		b.WriteString("\n")
	}

	// Files on separate lines
	label := fmt.Sprintf("%-*s", labelWidth, "Files")
	if len(r.Data.FilesTouched) == 0 {
		b.WriteString(m.styles.render(m.styles.gray, label))
		b.WriteString("—")
		b.WriteString("\n")
	} else {
		for i, f := range r.Data.FilesTouched {
			if i == 0 {
				b.WriteString(m.styles.render(m.styles.gray, label))
			} else {
				b.WriteString(m.styles.render(m.styles.gray, strings.Repeat(" ", labelWidth)))
			}
			b.WriteString(f)
			b.WriteString("\n")
		}
	}

	return b.String()
}

// computeColumns calculates column widths from terminal width.
func computeColumns(width int) columnLayout {
	const (
		idWidth     = 10
		authorWidth = 12
		ageWidth    = 8
		gaps        = 8 // 4 gaps x 2 chars
	)

	remaining := width - idWidth - authorWidth - ageWidth - gaps
	if remaining < 20 {
		remaining = 20
	}

	branchWidth := remaining * 20 / 100
	if branchWidth < 8 {
		branchWidth = 8
	}
	promptWidth := remaining - branchWidth

	return columnLayout{
		id:     idWidth,
		branch: branchWidth,
		prompt: promptWidth,
		author: authorWidth,
		age:    ageWidth,
	}
}

// formatSearchAge parses an RFC3339 timestamp and returns a relative time string.
func formatSearchAge(createdAt string) string {
	t, err := time.Parse(time.RFC3339, createdAt)
	if err != nil {
		return createdAt
	}
	return timeAgo(t)
}

// formatCommit renders commit SHA + message, handling nil pointers.
func formatCommit(sha, message *string) string {
	s := derefStr(sha, "—")
	if sha != nil && len(*sha) > 7 {
		s = (*sha)[:7]
	}
	msg := derefStr(message, "")
	if msg != "" {
		s += "  " + msg
	}
	return s
}

// formatAuthor renders author name with optional username.
func formatAuthor(author string, username *string) string {
	if username != nil && *username != "" {
		return author + " (@" + *username + ")"
	}
	return author
}

// formatCreatedAt renders a timestamp with relative time.
func formatCreatedAt(createdAt string) string {
	t, err := time.Parse(time.RFC3339, createdAt)
	if err != nil {
		return createdAt
	}
	return t.Format("Jan 02, 2006") + " (" + timeAgo(t) + ")"
}

// formatMatch renders match type and score.
func formatMatch(meta search.Meta) string {
	s := meta.MatchType
	if meta.Score > 0 {
		s += fmt.Sprintf(" (score: %.3f)", meta.Score)
	}
	return s
}

// derefStr returns the dereferenced string pointer, or fallback if nil.
func derefStr(s *string, fallback string) string {
	if s == nil {
		return fallback
	}
	return *s
}

// ptrFromStr returns a pointer to s, or nil if s is empty.
func ptrFromStr(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

// renderSearchStatic writes a non-interactive table for accessible mode.
func renderSearchStatic(w io.Writer, results []search.Result, query string, total int, styles statusStyles) {
	fmt.Fprintf(w, "Found %d checkpoints matching %q\n\n", total, query)

	cols := computeColumns(styles.width)

	// Header
	fmt.Fprintf(w, "%-*s  %-*s  %-*s  %-*s  %s\n",
		cols.id, "ID",
		cols.branch, "BRANCH",
		cols.prompt, "PROMPT",
		cols.author, "AUTHOR",
		"AGE",
	)

	for _, r := range results {
		id := stringutil.TruncateRunes(r.Data.ID, cols.id, "")
		branch := stringutil.TruncateRunes(r.Data.Branch, cols.branch, "...")
		prompt := stringutil.TruncateRunes(
			stringutil.CollapseWhitespace(r.Data.Prompt), cols.prompt, "...",
		)
		author := stringutil.TruncateRunes(r.Data.Author, cols.author, "...")
		age := formatSearchAge(r.Data.CreatedAt)

		fmt.Fprintf(w, "%-*s  %-*s  %-*s  %-*s  %s\n",
			cols.id, id,
			cols.branch, branch,
			cols.prompt, prompt,
			cols.author, author,
			age,
		)
	}
}

