		Short: "Search checkpoints using semantic and keyword matching",
		Long: `Search checkpoints using hybrid search (semantic + keyword),
powered by the Entire search service.

Requires authentication via 'entire login' (GitHub device flow).

Results are displayed in an interactive table. Use --json for
machine-readable output.`,
		Args: cobra.MinimumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			query := strings.Join(args, " ")

			ghToken, err := auth.LookupCurrentToken()
			if err != nil {
				return fmt.Errorf("reading credentials: %w", err)
			}
			if ghToken == "" {
				return errors.New("not authenticated. Run 'entire login' to authenticate")
			}

			// Get the repo's GitHub remote URL
			repo, err := strategy.OpenRepository(ctx)
			if err != nil {
				cmd.SilenceUsage = true
				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run this command from within a git repository.")
				return NewSilentError(err)
			}

			remote, err := repo.Remote("origin")
			if err != nil {
				return fmt.Errorf("could not find 'origin' remote: %w", err)
			}
			urls := remote.Config().URLs
			if len(urls) == 0 {
				return errors.New("origin remote has no URLs configured")
			}

			owner, repoName, err := search.ParseGitHubRemote(urls[0])
			if err != nil {
				return fmt.Errorf("parsing remote URL: %w", err)
			}

			serviceURL := os.Getenv("ENTIRE_SEARCH_URL")
			if serviceURL == "" {
				serviceURL = search.DefaultServiceURL
			}

			resp, err := search.Search(ctx, search.Config{
				ServiceURL:  serviceURL,
				GitHubToken: ghToken,
				Owner:       owner,
				Repo:        repoName,
				Query:       query,
				Limit:       limitFlag,
			})
			if err != nil {
				return fmt.Errorf("search failed: %w", err)
			}

			w := cmd.OutOrStdout()

			// Detect if stdout is a terminal
			isTerminal := false
			if f, ok := w.(*os.File); ok {
				isTerminal = term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
			}

			// JSON output: explicit flag or piped/redirected stdout
			if jsonOutput || !isTerminal {
				if len(resp.Results) == 0 {
					fmt.Fprintln(w, "[]")
					return nil
				}
				data, err := jsonutil.MarshalIndentWithNewline(resp.Results, "", "  ")
				if err != nil {
					return fmt.Errorf("marshaling results: %w", err)
				}
				fmt.Fprint(w, string(data))
				return nil
			}

			// No results
			if len(resp.Results) == 0 {
				fmt.Fprintln(w, "No results found.")
				return nil
			}

			styles := newStatusStyles(w)

			// Accessible mode: static table
			if IsAccessibleMode() {
				renderSearchStatic(w, resp.Results, query, resp.Total, styles)
				return nil
			}

			// Interactive TUI
			model := newSearchModel(resp.Results, query, resp.Total, styles)
			p := tea.NewProgram(model)
			if _, err := p.Run(); err != nil {
				return fmt.Errorf("TUI error: %w", err)
			}
			return nil
		},
	}

	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output as JSON")
	cmd.Flags().IntVar(&limitFlag, "limit", 20, "Maximum number of results")

	return cmd
}

package cli

import (
	"bytes"
	"strings"
	"testing"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/entireio/cli/cmd/entire/cli/search"
)

func testResults() []search.Result {
	sha1 := "e4f5a6b7c8d9"
	msg1 := "Implement auth middleware"
	user1 := "alicecodes"

	sha2 := "1a2b3c4d5e6f"
	msg2 := "Add JWT token refresh"

	return []search.Result{
		{
			Type: "checkpoint",
			Data: search.CheckpointResult{
				ID:             "a3b2c4d5e6f7",
				Prompt:         "add auth middleware to protect API routes",
				CommitSHA:      &sha1,
				CommitMessage:  &msg1,
				Branch:         "main",
				Org:            "entirehq",
				Repo:           "entire.io",
				Author:         "alice",
				AuthorUsername: &user1,
				CreatedAt:      "2026-03-24T10:30:00Z",
				FilesTouched:   []string{"src/middleware/auth.go", "src/handlers/login.go"},
			},
			Meta: search.Meta{
				MatchType: "semantic",
				Score:     0.042,
				Snippet:   "added auth middleware for JWT validation",
			},
		},
		{
			Type: "checkpoint",
			Data: search.CheckpointResult{
				ID:            "d5e6f789ab01",
				Prompt:        "fix auth token refresh",
				CommitSHA:     &sha2,
				CommitMessage: &msg2,
				Branch:        "feat/login",
				Org:           "entirehq",
				Repo:          "entire.io",
				Author:        "bob",
				CreatedAt:     "2026-03-20T14:00:00Z",
				FilesTouched:  []string{"src/auth/jwt.go"},
			},
			Meta: search.Meta{
				MatchType: "both",
				Score:     0.035,
			},
		},
	}
}

func testStyles() statusStyles {
	return statusStyles{
		colorEnabled: false,
		width:        80,
	}
}

func TestSearchModel_Navigation(t *testing.T) {
	t.Parallel()

	results := testResults()
	m := newSearchModel(results, "auth", 2, testStyles())

	if m.cursor != 0 {
		t.Fatalf("initial cursor = %d, want 0", m.cursor)
	}

	// Move down
	updated, _ := m.Update(tea.KeyMsg{Type: tea.KeyDown})
	m = updated.(searchModel)
	if m.cursor != 1 {
		t.Errorf("after down: cursor = %d, want 1", m.cursor)
	}

	// Move down at bottom — should clamp
	updated, _ = m.Update(tea.KeyMsg{Type: tea.KeyDown})
	m = updated.(searchModel)
	if m.cursor != 1 {
		t.Errorf("after down at bottom: cursor = %d, want 1", m.cursor)
	}

	// Move up
	updated, _ = m.Update(tea.KeyMsg{Type: tea.KeyUp})
	m = updated.(searchModel)
	if m.cursor != 0 {
		t.Errorf("after up: cursor = %d, want 0", m.cursor)
	}

	// Move up at top — should clamp
	updated, _ = m.Update(tea.KeyMsg{Type: tea.KeyUp})
	m = updated.(searchModel)
	if m.cursor != 0 {
		t.Errorf("after up at top: cursor = %d, want 0", m.cursor)
	}
}

func TestSearchModel_NavigationJK(t *testing.T) {
	t.Parallel()

	m := newSearchModel(testResults(), "auth", 2, testStyles())

	updated, _ := m.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'j'}})
	m = updated.(searchModel)
	if m.cursor != 1 {
		t.Errorf("after j: cursor = %d, want 1", m.cursor)
	}

	updated, _ = m.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'k'}})
	m = updated.(searchModel)
	if m.cursor != 0 {
		t.Errorf("after k: cursor = %d, want 0", m.cursor)
	}
}

func TestSearchModel_Quit(t *testing.T) {
	t.Parallel()

	m := newSearchModel(testResults(), "auth", 2, testStyles())

	quitKeys := []tea.KeyMsg{
		{Type: tea.KeyRunes, Runes: []rune{'q'}},
		{Type: tea.KeyEsc},
		{Type: tea.KeyCtrlC},
	}

	for _, key := range quitKeys {
		_, cmd := m.Update(key)
		if cmd == nil {
			t.Errorf("key %v: expected quit command, got nil", key)
			continue
		}
		// Execute the command to verify it produces a quit message
		msg := cmd()
		if _, ok := msg.(tea.QuitMsg); !ok {
			t.Errorf("key %v: expected QuitMsg, got %T", key, msg)
		}
	}
}

func TestSearchModel_View(t *testing.T) {
	t.Parallel()

	m := newSearchModel(testResults(), "auth", 2, testStyles())
	view := m.View()

	// Header
	if !strings.Contains(view, `Found 2 checkpoints matching "auth"`) {
		t.Error("view missing header")
	}

	// Column headers
	for _, col := range []string{"ID", "BRANCH", "PROMPT", "AUTHOR", "AGE"} {
		if !strings.Contains(view, col) {
			t.Errorf("view missing column header %q", col)
		}
	}

	// First result data in table
	if !strings.Contains(view, "a3b2c4d5e6") {
		t.Error("view missing truncated ID")
	}
	if !strings.Contains(view, "main") {
		t.Error("view missing branch")
	}

	// Detail panel for selected (first) result
	if !strings.Contains(view, "a3b2c4d5e6f7") {
		t.Error("detail missing full ID")
	}
	if !strings.Contains(view, "add auth middleware to protect API routes") {
		t.Error("detail missing full prompt")
	}
	if !strings.Contains(view, "e4f5a6b") {
		t.Error("detail missing commit SHA")
	}
	if !strings.Contains(view, "entirehq/entire.io") {
		t.Error("detail missing repo")
	}
	if !strings.Contains(view, "@alicecodes") {
		t.Error("detail missing username")
	}
	if !strings.Contains(view, "semantic") {
		t.Error("detail missing match type")
	}
	if !strings.Contains(view, "src/middleware/auth.go") {
		t.Error("detail missing files")
	}

	// Footer
	if !strings.Contains(view, "navigate") {
		t.Error("view missing footer")
	}
}

func TestSearchModel_ViewNoColor(t *testing.T) {
	t.Parallel()

	m := newSearchModel(testResults(), "auth", 2, testStyles())
	view := m.View()

	// Selected row should have "> " prefix when color disabled
	lines := strings.Split(view, "\n")
	foundSelected := false
	for _, line := range lines {
		if strings.HasPrefix(line, "> ") && strings.Contains(line, "a3b2c4d5e6") {
			foundSelected = true
			break
		}
	}
	if !foundSelected {
		t.Error("selected row missing '> ' prefix in no-color mode")
	}

	// Non-selected row should have "  " prefix
	foundNormal := false
	for _, line := range lines {
		if strings.HasPrefix(line, "  ") && strings.Contains(line, "d5e6f789ab") {
			foundNormal = true
			break
		}
	}
	if !foundNormal {
		t.Error("non-selected row missing '  ' prefix in no-color mode")
	}
}

func TestSearchModel_WindowResize(t *testing.T) {
	t.Parallel()

	m := newSearchModel(testResults(), "auth", 2, testStyles())
	if m.width != 80 {
		t.Fatalf("initial width = %d, want 80", m.width)
	}

	updated, _ := m.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	m = updated.(searchModel)
	if m.width != 120 {
		t.Errorf("after resize: width = %d, want 120", m.width)
	}
}

func TestSearchModel_ViewZeroWidth(t *testing.T) {
	t.Parallel()

	styles := testStyles()
	styles.width = 0
	m := newSearchModel(testResults(), "auth", 2, styles)
	m.width = 0

	view := m.View()
	if view != "" {
		t.Errorf("view with zero width should be empty, got %q", view)
	}
}

func TestFormatSearchAge(t *testing.T) {
	t.Parallel()

	// Valid RFC3339
	age := formatSearchAge("2026-03-25T10:00:00Z")
	if age == "2026-03-25T10:00:00Z" {
		t.Error("formatSearchAge returned raw timestamp instead of relative time")
	}

	// Invalid format — returns raw string
	age = formatSearchAge("not-a-date")
	if age != "not-a-date" {
		t.Errorf("formatSearchAge for invalid date = %q, want %q", age, "not-a-date")
	}
}

func TestDerefStr(t *testing.T) {
	t.Parallel()

	// Nil case
	if got := derefStr(nil, "fallback"); got != "fallback" {
		t.Errorf("derefStr(nil) = %q, want %q", got, "fallback")
	}

	// Non-nil case
	s := "hello"
	if got := derefStr(&s, "fallback"); got != "hello" {
		t.Errorf("derefStr(&s) = %q, want %q", got, "hello")
	}
}

