	t.Parallel()

	var buf bytes.Buffer
	results := testResults()
	styles := testStyles()

	renderSearchStatic(&buf, results, "auth", 2, styles)
	output := buf.String()

	if !strings.Contains(output, `Found 2 checkpoints matching "auth"`) {
