package cli

import (
	"context"
	"fmt"
	"io"
	"strings"
	"time"

	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/search"
	"github.com/entireio/cli/cmd/entire/cli/stringutil"
)

// searchMode tracks whether the user is browsing results or editing the search bar.
type searchMode int

const (
	modeBrowse searchMode = iota
	modeSearch
)

// searchResultsMsg is sent when a search API call completes.
type searchResultsMsg struct {
	results []search.Result
	total   int
	err     error
}

// searchModel is the bubbletea model for interactive search results.
type searchModel struct {
	results    []search.Result
	cursor     int
	total      int
	width      int
	height     int
	mode       searchMode
	loading    bool
	searchErr  string
	input      textinput.Model
	searchCfg  search.Config // config for re-searching (minus Query)
	useColor   bool
	labelStyle lipgloss.Style
	idStyle    lipgloss.Style
	branchStyle lipgloss.Style
	dimStyle   lipgloss.Style
	boldStyle  lipgloss.Style
	selStyle   lipgloss.Style
	headerStyle lipgloss.Style
	helpKeyStyle lipgloss.Style
	matchStyle lipgloss.Style
}

func newSearchModel(results []search.Result, query string, total int, cfg search.Config, styles statusStyles) searchModel {
	ti := textinput.New()
	ti.SetValue(query)
	ti.Prompt = "  Search: "
	ti.CharLimit = 200
	ti.Width = max(styles.width-12, 30)
	if styles.colorEnabled {
		ti.PromptStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("6")).Bold(true)
		ti.TextStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("15"))
		ti.Cursor.Style = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
	}

	m := searchModel{
		results:   results,
		cursor:    0,
		total:     total,
		width:     styles.width,
		mode:      modeBrowse,
		input:     ti,
		searchCfg: cfg,
		useColor:  styles.colorEnabled,
	}

	if styles.colorEnabled {
		m.labelStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
		m.idStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Bold(true)
		m.branchStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
		m.dimStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
		m.boldStyle = lipgloss.NewStyle().Bold(true)
		m.selStyle = lipgloss.NewStyle().Background(lipgloss.Color("237")).Bold(true)
		m.headerStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true)
		m.helpKeyStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("6")).Bold(true)
		m.matchStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
	}

	return m
}

func (m searchModel) Init() tea.Cmd {
	return nil
}

func (m searchModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn,cyclop // bubbletea interface
	switch msg := msg.(type) {
	case searchResultsMsg:
		m.loading = false
		if msg.err != nil {
			m.searchErr = msg.err.Error()
			return m, nil
		}
		m.searchErr = ""
		m.results = msg.results
		m.total = msg.total
		m.cursor = 0
		return m, nil

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.input.Width = max(msg.Width-12, 30)
		return m, nil

	case tea.KeyMsg:
		if m.mode == modeSearch {
			return m.updateSearchMode(msg)
		}
		return m.updateBrowseMode(msg)
	}
	return m, nil
}

func (m searchModel) updateSearchMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.mode = modeBrowse
		m.input.Blur()
		return m, nil
	case "enter":
		query := strings.TrimSpace(m.input.Value())
		if query == "" {
			return m, nil
		}
		m.mode = modeBrowse
		m.input.Blur()
		m.loading = true
		m.searchErr = ""
		cfg := m.searchCfg
		cfg.Query = query
		return m, performSearch(cfg)
	}

	var cmd tea.Cmd
	m.input, cmd = m.input.Update(msg)
	return m, cmd
}

func (m searchModel) updateBrowseMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "q", "ctrl+c":
		return m, tea.Quit
	case "up", "k":
		if m.cursor > 0 {
			m.cursor--
		}
	case "down", "j":
		if m.cursor < len(m.results)-1 {
			m.cursor++
		}
	case "/":
		m.mode = modeSearch
		m.input.Focus()
		return m, m.input.Cursor.SetMode(textinput.CursorBlink)
	}
	return m, nil
}

func performSearch(cfg search.Config) tea.Cmd {
	return func() tea.Msg {
		resp, err := search.Search(context.Background(), cfg)
		if err != nil {
			return searchResultsMsg{err: err}
		}
		return searchResultsMsg{results: resp.Results, total: resp.Total}
	}
}

func (m searchModel) View() string {
	if m.width == 0 {
		return ""
	}

	var b strings.Builder

	// Search bar
	b.WriteString(m.viewSearchBar())
	b.WriteString("\n")

	if m.loading {
		b.WriteString(m.renderStyled(m.dimStyle, "  Searching..."))
		b.WriteString("\n")
		return b.String()
	}

	if m.searchErr != "" {
		b.WriteString(m.renderStyled(lipgloss.NewStyle().Foreground(lipgloss.Color("1")), "  Error: "+m.searchErr))
		b.WriteString("\n")
		return b.String()
	}

	if len(m.results) == 0 {
		b.WriteString(m.renderStyled(m.dimStyle, "  No results found."))
		b.WriteString("\n")
		return b.String()
	}

	// Results count
	countStr := fmt.Sprintf("  %d results", m.total)
	b.WriteString(m.renderStyled(m.dimStyle, countStr))
	b.WriteString("\n\n")

	// Table
	b.WriteString(m.viewTable())

	// Separator
	b.WriteString("\n")
	sep := "  " + strings.Repeat("─", max(m.width-4, 20))
	b.WriteString(m.renderStyled(m.dimStyle, sep))
	b.WriteString("\n\n")

	// Detail panel
	if m.cursor >= 0 && m.cursor < len(m.results) {
		b.WriteString(m.viewDetail(m.results[m.cursor]))
	}

	// Footer help
	b.WriteString(m.viewHelp())

	return b.String()
}

func (m searchModel) viewSearchBar() string {
	var bar string
	if m.mode == modeSearch {
		bar = m.input.View()
	} else {
		// Show static search bar
		query := m.input.Value()
		if m.useColor {
			bar = "  " + m.renderStyled(m.branchStyle, "Search: ") + m.renderStyled(m.boldStyle, query)
		} else {
			bar = "  Search: " + query
		}
	}

	border := strings.Repeat("─", max(m.width-4, 20))
	return bar + "\n" + m.renderStyled(m.dimStyle, "  "+border)
}

func (m searchModel) viewTable() string {
	cols := computeColumns(m.width - 4) // account for padding

	var b strings.Builder

	// Column headers
	hdr := fmt.Sprintf("  %-*s %-*s %-*s %-*s %s",
		cols.id, "ID",
		cols.branch, "BRANCH",
		cols.prompt, "PROMPT",
		cols.author, "AUTHOR",
		"AGE",
	)
	b.WriteString(m.renderStyled(m.headerStyle, hdr))
	b.WriteString("\n")

	// Rows
	for i, r := range m.results {
		row := m.viewRow(r, cols)
		if i == m.cursor {
			if m.useColor {
				// Full-width highlight
				padded := row + strings.Repeat(" ", max(0, m.width-lipgloss.Width(row)))
				b.WriteString(m.selStyle.Render(padded))
			} else {
				b.WriteString("> " + row)
			}
		} else {
			b.WriteString("  " + row)
		}
		b.WriteString("\n")
	}

	return b.String()
}

func (m searchModel) viewRow(r search.Result, cols columnLayout) string {
	id := stringutil.TruncateRunes(r.Data.ID, cols.id, "")
	branch := stringutil.TruncateRunes(r.Data.Branch, cols.branch, "...")
	prompt := stringutil.TruncateRunes(
		stringutil.CollapseWhitespace(r.Data.Prompt), cols.prompt, "...",
	)
	author := stringutil.TruncateRunes(r.Data.Author, cols.author, "...")
	age := formatSearchAge(r.Data.CreatedAt)

	if !m.useColor {
		return fmt.Sprintf("%-*s %-*s %-*s %-*s %s",
			cols.id, id,
			cols.branch, branch,
			cols.prompt, prompt,
			cols.author, author,
			age,
		)
	}

	return fmt.Sprintf("%-*s %-*s %-*s %-*s %s",
		cols.id+ansiExtra(m.idStyle, id), m.idStyle.Render(id),
		cols.branch+ansiExtra(m.branchStyle, branch), m.branchStyle.Render(branch),
		cols.prompt, prompt,
		cols.author+ansiExtra(m.dimStyle, author), m.dimStyle.Render(author),
		m.dimStyle.Render(age),
	)
}

func (m searchModel) viewDetail(r search.Result) string {
	const pad = "  "
	const labelWidth = 14
	var b strings.Builder

	writeField := func(label, value string) {
		lbl := fmt.Sprintf("%-*s", labelWidth, label)
		b.WriteString(pad)
		b.WriteString(m.renderStyled(m.labelStyle, lbl))
		b.WriteString(value)
		b.WriteString("\n")
	}

	writeStyledField := func(label string, style lipgloss.Style, value string) {
		lbl := fmt.Sprintf("%-*s", labelWidth, label)
		b.WriteString(pad)
		b.WriteString(m.renderStyled(m.labelStyle, lbl))
		b.WriteString(m.renderStyled(style, value))
		b.WriteString("\n")
	}

	writeStyledField("ID", m.idStyle, r.Data.ID)
	writeField("Type", r.Type)
	writeField("Prompt", r.Data.Prompt)

	// Commit with styled SHA
	commitSHA := derefStr(r.Data.CommitSHA, "—")
	if r.Data.CommitSHA != nil && len(*r.Data.CommitSHA) > 7 {
		commitSHA = (*r.Data.CommitSHA)[:7]
	}
	commitMsg := derefStr(r.Data.CommitMessage, "")
	if commitMsg != "" {
		commitVal := m.renderStyled(m.idStyle, commitSHA) + "  " + commitMsg
		lbl := fmt.Sprintf("%-*s", labelWidth, "Commit")
		b.WriteString(pad)
		b.WriteString(m.renderStyled(m.labelStyle, lbl))
		b.WriteString(commitVal)
		b.WriteString("\n")
	} else {
		writeStyledField("Commit", m.idStyle, commitSHA)
	}

	writeStyledField("Branch", m.branchStyle, r.Data.Branch)
	writeField("Repo", r.Data.Org+"/"+r.Data.Repo)
	writeField("Author", formatAuthor(r.Data.Author, r.Data.AuthorUsername))
	writeField("Created", formatCreatedAt(r.Data.CreatedAt))
	writeStyledField("Match", m.matchStyle, formatMatch(r.Meta))

	snippet := r.Meta.Snippet
	if snippet != "" {
		writeField("Snippet", snippet)
	}

	// Files
	if len(r.Data.FilesTouched) == 0 {
		writeField("Files", "—")
	} else {
		for i, f := range r.Data.FilesTouched {
			if i == 0 {
				writeField("Files", f)
			} else {
				b.WriteString(pad)
				b.WriteString(m.renderStyled(m.labelStyle, strings.Repeat(" ", labelWidth)))
				b.WriteString(f)
				b.WriteString("\n")
			}
		}
	}

	return b.String()
}

func (m searchModel) viewHelp() string {
	var parts []string

	if m.mode == modeSearch {
		parts = []string{
			m.renderStyled(m.helpKeyStyle, "enter") + " search",
			m.renderStyled(m.helpKeyStyle, "esc") + " cancel",
		}
	} else {
		parts = []string{
			m.renderStyled(m.helpKeyStyle, "↑/↓") + " navigate",
			m.renderStyled(m.helpKeyStyle, "/") + " search",
			m.renderStyled(m.helpKeyStyle, "q") + " quit",
		}
	}

	return "\n  " + strings.Join(parts, "    ") + "\n"
}

// renderStyled applies a lipgloss style, returning plain text when color is off.
func (m searchModel) renderStyled(style lipgloss.Style, text string) string {
	if !m.useColor {
		return text
	}
	return style.Render(text)
}

// ansiExtra returns the number of extra bytes added by ANSI escape codes
// when rendering text with a style. Used for %-*s width compensation.
func ansiExtra(style lipgloss.Style, text string) int {
	return lipgloss.Width(style.Render(text)) - lipgloss.Width(text) + len(style.Render(text)) - len(text)
}

// columnLayout holds computed column widths for the search results table.
type columnLayout struct {
	id     int
	branch int
	prompt int
	author int
	age    int
}

// computeColumns calculates column widths from terminal width.
func computeColumns(width int) columnLayout {
	const (
		idWidth     = 10
		authorWidth = 12
		ageWidth    = 8
		gaps        = 4 // 4 gaps x 1 char
	)

	remaining := width - idWidth - authorWidth - ageWidth - gaps
	if remaining < 20 {
		remaining = 20
	}

	branchWidth := remaining * 25 / 100
	if branchWidth < 8 {
		branchWidth = 8
	}
	promptWidth := remaining - branchWidth

	return columnLayout{
		id:     idWidth,
		branch: branchWidth,
		prompt: promptWidth,
		author: authorWidth,
		age:    ageWidth,
	}
}

// formatSearchAge parses an RFC3339 timestamp and returns a relative time string.
func formatSearchAge(createdAt string) string {
	t, err := time.Parse(time.RFC3339, createdAt)
	if err != nil {
		return createdAt
	}
	return timeAgo(t)
}

// formatCommit renders commit SHA + message, handling nil pointers.
func formatCommit(sha, message *string) string {
	s := derefStr(sha, "—")
	if sha != nil && len(*sha) > 7 {
		s = (*sha)[:7]
	}
	msg := derefStr(message, "")
	if msg != "" {
		s += "  " + msg
	}
	return s
}

// formatAuthor renders author name with optional username.
func formatAuthor(author string, username *string) string {
	if username != nil && *username != "" {
		return author + " (@" + *username + ")"
	}
	return author
}

// formatCreatedAt renders a timestamp with relative time.
func formatCreatedAt(createdAt string) string {
	t, err := time.Parse(time.RFC3339, createdAt)
	if err != nil {
		return createdAt
	}
	return t.Format("Jan 02, 2006") + " (" + timeAgo(t) + ")"
}

// formatMatch renders match type and score.
func formatMatch(meta search.Meta) string {
	s := meta.MatchType
	if meta.Score > 0 {
		s += fmt.Sprintf(" (score: %.3f)", meta.Score)
	}
	return s
}

// derefStr returns the dereferenced string pointer, or fallback if nil.
func derefStr(s *string, fallback string) string {
	if s == nil {
		return fallback
	}
	return *s
}

// ptrFromStr returns a pointer to s, or nil if s is empty.
func ptrFromStr(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

// renderSearchStatic writes a non-interactive table for accessible mode.
func renderSearchStatic(w io.Writer, results []search.Result, query string, total int, styles statusStyles) {
	fmt.Fprintf(w, "Found %d checkpoints matching %q\n\n", total, query)

	cols := computeColumns(styles.width)

	fmt.Fprintf(w, "%-*s  %-*s  %-*s  %-*s  %s\n",
		cols.id, "ID",
		cols.branch, "BRANCH",
		cols.prompt, "PROMPT",
		cols.author, "AUTHOR",
		"AGE",
	)

	for _, r := range results {
		id := stringutil.TruncateRunes(r.Data.ID, cols.id, "")
		branch := stringutil.TruncateRunes(r.Data.Branch, cols.branch, "...")
		prompt := stringutil.TruncateRunes(
			stringutil.CollapseWhitespace(r.Data.Prompt), cols.prompt, "...",
		)
		author := stringutil.TruncateRunes(r.Data.Author, cols.author, "...")
		age := formatSearchAge(r.Data.CreatedAt)

		fmt.Fprintf(w, "%-*s  %-*s  %-*s  %-*s  %s\n",
			cols.id, id,
			cols.branch, branch,
			cols.prompt, prompt,
			cols.author, author,
			age,
		)
	}
}

